function solve(input) {
  return input.filter(l => !['intuition','hypothesis','disputed'].includes(l.type) && 
                    (l.value < 0 || 
                     (!input.some(other => other.value < 0 && 
 other.subject === l.subject && 
 other.predicate === l.predicate && 
 other.scope === l.scope && 
 other.value !== l.value)))); 
}
